    function modal(title,body,save,wide){var bg=$('#modalBg');if(!bg){bg=document.createElement('div');bg.id='modalBg';bg.className='modal-bg';document.body.appendChild(bg)}bg.innerHTML='<div class="modal-box" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-head"><h3 id="modalTitle">'+h(title)+'</h3><button class="modal-close" data-close aria-label="关闭">×</button></div><div class="modal-body"><div class="err" role="alert"></div>'+body+'</div><div class="modal-foot"><button class="secondary" data-close>取消</button><button class="primary" id="modalSave">保存</button></div></div>';bg.classList.add('open');bg.querySelector('#modalSave').onclick=function(){save(bg)};$$('[data-close]',bg).forEach(function(x){x.onclick=closeModal});bg.onclick=function(e){if(e.target===bg)closeModal()};var first=bg.querySelector('input,select,textarea');if(first)setTimeout(function(){first.focus()},0)}
