      modal((old?'编辑':'新增')+label,b,function(bg){var d={};$$('[name]',bg).forEach(function(e){d[e.name]=e.value});try{store.saveEntity(type,d,id);closeModal();render();toast(label+(old?'已更新':'已新增'),true)}catch(e){errorIn(bg,failText(e))}});if(old)$$('select',document.querySelector('#modalBg')).forEach(function(x){if(old[x.name]!==undefined)x.value=old[x.name]})
