      var statLabels=$$('.stats .stat-top > span:first-child'),statNums=$$('.stats .stat strong'),statSubs=$$('.stats .stat small');statLabels[2].textContent='有库存物品';statLabels[3].textContent='低于安全库存';statNums[2].textContent=s.items.filter(function(i){return rows.some(function(r){return r.itemId===i.id&&r.quantity>0})}).length;statSubs[2].textContent=Object.keys(units).map(function(u){return num(units[u])+' '+u}).join(' · ')||'暂无已确认库存';
      var grid=$('.grid',d);grid.innerHTML='<section class="panel"><div class="panel-head"><h2>已确认库存 · 按单位展示</h2><button class="text-btn" data-view-link="inventory">查看流水 →</button></div><div class="panel-body">'+(Object.keys(units).map(function(u){return '<div class="health-row"><span>'+h(u)+'</span><b>'+num(units[u])+' '+h(u)+'</b></div>'}).join('')||'<div class="empty-note">尚无已确认库存</div>')+'</div></section><section class="panel"><div class="panel-head"><h2>处理概况</h2><span style="color:var(--muted);font-size:12px">当前本地数据</span></div><div class="panel-body"><div class="health-row"><span>基础档案</span><b>'+(s.factories.length+s.warehouses.length+s.people.length+s.items.length)+' 条</b></div><div class="health-row"><span>已确认流水</span><b>'+confirmed+' 条</b></div><div class="health-row"><span>待审核流水</span><b class="warn">'+pending+' 条</b></div></div></section>';
